// ── Thread-local GL state ───────────────────────────────────────────────

struct GlState {
    #[cfg(not(target_os = "android"))]
    #[allow(dead_code)] // kept alive to prevent window destruction
    window: winit::window::Window,
    #[cfg(not(target_os = "android"))]
    surface: glutin::surface::Surface<glutin::surface::WindowSurface>,
    #[cfg(not(target_os = "android"))]
    context: glutin::context::PossiblyCurrentContext,
    #[cfg(not(target_os = "android"))]
    event_loop: winit::event_loop::EventLoop<()>,
    // Android: raw EGL/GLES surface on the ANativeWindow (see `android_gl`).
    #[cfg(target_os = "android")]
    android: android_gl::AndroidGl,
    should_close: bool,
    // GL viewport size chosen at creation (selected-monitor size for
    // fullscreen) — returned by the window-size getters so callers don't
    // race the async inner_size update after a monitor move.
    viewport_w: u32,
    viewport_h: u32,
}

thread_local! {
    static GL: RefCell<Option<GlState>> = const { RefCell::new(None) };
    /// Set to `true` only after `gl::load_with` succeeds inside
    /// `loft_gl_create_window`.  Every function that calls a `gl::*`
    /// entry-point must check this first — when GL function pointers are
    /// not loaded, calling through them is undefined behaviour (P130).
    static GL_READY: Cell<bool> = const { Cell::new(false) };
}

/// Early-return when GL function pointers have not been loaded.
/// Use `gl_guard!()` in void functions and `gl_guard!(expr)` to return a
/// default value.
macro_rules! gl_guard {
    () => {
        if !GL_READY.with(|c| c.get()) {
            return;
        }
    };
    ($default:expr) => {
        if !GL_READY.with(|c| c.get()) {
            return $default;
        }
    };
}

fn with_gl<R>(f: impl FnOnce(&GlState) -> R) -> Option<R> {
    GL.with(|cell| cell.borrow().as_ref().map(f))
}

fn with_gl_mut<R>(f: impl FnOnce(&mut GlState) -> R) -> Option<R> {
    GL.with(|cell| cell.borrow_mut().as_mut().map(f))
}

// ── Input state ────────────────────────────────────────────────────────

thread_local! {
    static KEYS: RefCell<[bool; 256]> = const { RefCell::new([false; 256]) };
    static MOUSE_X: std::cell::Cell<f64> = const { std::cell::Cell::new(0.0) };
    static MOUSE_Y: std::cell::Cell<f64> = const { std::cell::Cell::new(0.0) };
    static MOUSE_BTN: std::cell::Cell<u8> = const { std::cell::Cell::new(0) };
    /// Initiative 03 Phase 1: scroll-wheel accumulator.  `MouseWheel`
    /// events add to this cell; `loft_gl_mouse_wheel` reads-and-resets.
    /// Positive = scroll up.  Pixel deltas are converted to integer
    /// line counts via a 20-px-per-line heuristic — winit reports
    /// either `LineDelta` (mouse) or `PixelDelta` (trackpad).
    static WHEEL_ACCUM: std::cell::Cell<i64> = const { std::cell::Cell::new(0) };
    /// Pending resize from a WindowEvent::Resized, applied after pump_app_events.
    static PENDING_RESIZE: std::cell::Cell<Option<(u32, u32)>> = const { std::cell::Cell::new(None) };
}

// @PLN106 B4 — Android touch feeds the SAME shared pointer state the desktop path fills from
// winit events, so `loft_gl_mouse_x/y/button` read touch identically (no new loft API). Called
// from `android_gl::poll` on the `android_main` thread — the same thread the loft program runs
// on, so these thread-local cells are shared with the `gl_mouse_*` reads.
#[cfg(target_os = "android")]
pub(crate) fn set_pointer_pos(x: f64, y: f64) {
    MOUSE_X.with(|c| c.set(x));
    MOUSE_Y.with(|c| c.set(y));
}
#[cfg(target_os = "android")]
pub(crate) fn set_pointer_down(down: bool) {
    // Touch maps to the left mouse button (bit 0), matching the desktop `MouseButton::Left`.
    MOUSE_BTN.with(|c| c.set(u8::from(down)));
}
/// @PLN106 B4 IME — set a key's pressed state (`idx` is the 0-255 index `gl_key_pressed`
/// reads, matching the desktop `key_index` scheme). Called from `android_gl::drain_input`.
#[cfg(target_os = "android")]
pub(crate) fn set_key(idx: u8, pressed: bool) {
    KEYS.with(|k| k.borrow_mut()[idx as usize] = pressed);
}

// Map winit key codes to a simple 0-255 index. Desktop-only; Android input is B4.
#[cfg(not(target_os = "android"))]
fn key_index(key: &winit::keyboard::Key) -> Option<u8> {
    use winit::keyboard::NamedKey;
    match key {
        winit::keyboard::Key::Character(c) => {
            let ch = c.chars().next()?;
            if ch.is_ascii() {
                Some(ch.to_ascii_lowercase() as u8)
            } else {
                None
            }
        }
        winit::keyboard::Key::Named(n) => match n {
            NamedKey::Space => Some(b' '),
            NamedKey::Enter => Some(b'\r'),
            NamedKey::Escape => Some(27),
            NamedKey::Tab => Some(9),
            NamedKey::ArrowUp => Some(128),
            NamedKey::ArrowDown => Some(129),
            NamedKey::ArrowLeft => Some(130),
            NamedKey::ArrowRight => Some(131),
            NamedKey::Shift => Some(132),
            NamedKey::Control => Some(133),
            // Initiative 03 Phase 1: F-keys for editor hotkeys.
            // F5 / F9 / F11 land at 134 / 138 / 140; siblings are
            // reserved even though the current editor only binds
            // F5 / F9 / F11, so later additions don't shift indices.
            NamedKey::F1 => Some(135),
            NamedKey::F2 => Some(136),
            NamedKey::F3 => Some(137),
            NamedKey::F4 => Some(138),
            NamedKey::F5 => Some(139),
            NamedKey::F6 => Some(140),
            NamedKey::F7 => Some(141),
            NamedKey::F8 => Some(142),
            NamedKey::F9 => Some(143),
            NamedKey::F10 => Some(144),
            NamedKey::F11 => Some(145),
            NamedKey::F12 => Some(146),
            _ => None,
        },
        _ => None,
    }
}

#[cfg(not(target_os = "android"))]
struct JsonApp {
    should_close: bool,
}

#[cfg(not(target_os = "android"))]
impl ApplicationHandler for JsonApp {
    fn resumed(&mut self, _event_loop: &ActiveEventLoop) {}
    fn window_event(&mut self, _el: &ActiveEventLoop, _id: WindowId, event: WindowEvent) {
        match event {
            WindowEvent::CloseRequested => self.should_close = true,
            WindowEvent::KeyboardInput { event, .. } => {
                if let Some(idx) = key_index(&event.logical_key) {
                    KEYS.with(|k| k.borrow_mut()[idx as usize] = event.state.is_pressed());
                }
            }
            WindowEvent::CursorMoved { position, .. } => {
                MOUSE_X.with(|c| c.set(position.x));
                MOUSE_Y.with(|c| c.set(position.y));
            }
            WindowEvent::MouseInput { state, button, .. } => {
                let bit = match button {
                    winit::event::MouseButton::Left => 1u8,
                    winit::event::MouseButton::Right => 2,
                    winit::event::MouseButton::Middle => 4,
                    _ => 0,
                };
                MOUSE_BTN.with(|c| {
                    if state.is_pressed() {
                        c.set(c.get() | bit);
                    } else {
                        c.set(c.get() & !bit);
                    }
                });
            }
            WindowEvent::MouseWheel { delta, .. } => {
                use winit::event::MouseScrollDelta;
                let ticks: i64 = match delta {
                    MouseScrollDelta::LineDelta(_dx, dy) => dy as i64,
                    // Trackpad pixel-delta: convert with a 20 px/line
                    // heuristic; matches the default scroll granularity
                    // most 3D apps use.
                    MouseScrollDelta::PixelDelta(p) => (p.y / 20.0) as i64,
                };
                if ticks != 0 {
                    WHEEL_ACCUM.with(|c| c.set(c.get() + ticks));
                }
            }
            WindowEvent::Resized(size) => {
                let w = size.width;
                let h = size.height;
                if w > 0 && h > 0 {
                    PENDING_RESIZE.with(|c| c.set(Some((w, h))));
                }
            }
            _ => {}
        }
    }
}

// ── C-ABI exports ───────────────────────────────────────────────────────

#[loft_native]
#[unsafe(no_mangle)]
pub extern "C" fn loft_gl_create_window(
    width: u32,
    height: u32,
    title_ptr: *const u8,
    title_len: usize,
) -> bool {
    let title = unsafe { loft_ffi::text(title_ptr, title_len) };
    match window::create_gl_state(width, height, title) {
        Ok(state) => {
            GL.with(|cell| *cell.borrow_mut() = Some(state));
            GL_READY.with(|c| c.set(true));
            true
        }
        Err(e) => {
            eprintln!("loft_gl_create_window: {e}");
            false
        }
    }
}

/// Initiative 03 Phase 0: borderless fullscreen companion to
/// `loft_gl_create_window`.  Opens on the primary monitor at its
/// native resolution.  Returns `true` on success.
#[loft_native]
#[unsafe(no_mangle)]
pub extern "C" fn loft_gl_create_fullscreen_window(title_ptr: *const u8, title_len: usize) -> bool {
    let title = unsafe { loft_ffi::text(title_ptr, title_len) };
    match window::create_gl_state_fullscreen(title) {
        Ok(state) => {
            GL.with(|cell| *cell.borrow_mut() = Some(state));
            GL_READY.with(|c| c.set(true));
            true
        }
        Err(e) => {
            eprintln!("loft_gl_create_fullscreen_window: {e}");
            false
        }
    }
}

/// Initiative 03 Phase 4: toggle fullscreen on the existing window.
/// Cheaper than destroying + recreating the GL context — winit flips
/// the window mode at runtime and all GL resources (textures, VAOs,
/// shaders, FBOs) survive.  Pass `true` for borderless fullscreen on
/// the current monitor, `false` to return to the windowed size
/// `gl_create_window` originally opened.
#[loft_native]
#[unsafe(no_mangle)]
pub extern "C" fn loft_gl_set_fullscreen(on: bool) {
    #[cfg(not(target_os = "android"))]
    {
        use winit::window::Fullscreen;
        with_gl(|s| {
            if on {
                s.window.set_fullscreen(Some(Fullscreen::Borderless(None)));
            } else {
                s.window.set_fullscreen(None);
            }
        });
    }
    // An Android NativeActivity is always fullscreen — nothing to toggle.
    #[cfg(target_os = "android")]
    let _ = on;
}

/// Current window inner size in physical pixels.  Needed because a
/// fullscreen window opens at the monitor's native resolution, so callers
/// can't assume their windowed hint — query the real size to build the
/// projection / 2D ortho / overlay placement correctly.  Returns 0 if no
/// window exists.
#[loft_native]
#[unsafe(no_mangle)]
pub extern "C" fn loft_gl_window_width() -> i64 {
    gl_guard!(0);
    with_gl(|s| s.viewport_w as i64).unwrap_or(0)
}

#[loft_native]
#[unsafe(no_mangle)]
pub extern "C" fn loft_gl_window_height() -> i64 {
    gl_guard!(0);
    with_gl(|s| s.viewport_h as i64).unwrap_or(0)
}

#[loft_native]
#[unsafe(no_mangle)]
pub extern "C" fn loft_gl_poll_events() -> bool {
    #[cfg(target_os = "android")]
    {
        return with_gl_mut(android_gl::poll).unwrap_or(false);
    }
    #[cfg(not(target_os = "android"))]
    with_gl_mut(|s| {
        let mut handler = JsonApp {
            should_close: false,
        };
        let status = s
            .event_loop
            .pump_app_events(Some(Duration::ZERO), &mut handler);
        if handler.should_close || matches!(status, PumpStatus::Exit(_)) {
            s.should_close = true;
        }
        // Apply any pending resize — the handler can't borrow GlState directly.
        if let Some((w, h)) = PENDING_RESIZE.with(|c| c.take())
            && let (Some(nw), Some(nh)) =
                (std::num::NonZeroU32::new(w), std::num::NonZeroU32::new(h))
        {
            s.surface.resize(&s.context, nw, nh);
            unsafe {
                gl::Viewport(0, 0, w as i32, h as i32);
            }
            // Keep the window-size getters in sync with the actual
            // surface — otherwise `loft_gl_window_width/height` keep
            // returning the stale creation-time hint after the window
            // manager resizes the window to fit the screen, and any
            // screen-space UI hit-testing built on them is vertically
            // offset from where it draws.
            s.viewport_w = w;
            s.viewport_h = h;
        }
        !s.should_close
    })
    .unwrap_or(false)
}

#[loft_native]
#[unsafe(no_mangle)]
pub extern "C" fn loft_gl_swap_buffers() {
    gl_guard!();
    // On Wayland the compositor uses framebuffer alpha for window
    // transparency. Force the alpha channel to 1.0 (opaque) on every
    // frame before presenting, regardless of what shaders wrote.
    unsafe {
        gl::ColorMask(gl::FALSE, gl::FALSE, gl::FALSE, gl::TRUE);
        gl::ClearColor(0.0, 0.0, 0.0, 1.0);
        gl::Clear(gl::COLOR_BUFFER_BIT);
        gl::ColorMask(gl::TRUE, gl::TRUE, gl::TRUE, gl::TRUE);
    }
    with_gl(|s| {
        #[cfg(not(target_os = "android"))]
        let _ = s.surface.swap_buffers(&s.context);
        #[cfg(target_os = "android")]
        android_gl::swap(s);
    });
}

#[loft_native]
#[unsafe(no_mangle)]
pub extern "C" fn loft_gl_clear(color: i64) {
    // `i64`, not `u32`: the loft side declares `gl_clear(color: integer)`, and loft
    // emits the extern from that declaration, so it passes 64 bits.  Narrow the packed
    // 0xAARRGGBB colour here rather than in the signature.
    let color = color as u32;
    gl_guard!();
    // Color is packed as 0xAARRGGBB by graphics::rgba().
    let a = ((color >> 24) & 0xFF) as f32 / 255.0;
    let r = ((color >> 16) & 0xFF) as f32 / 255.0;
    let g = ((color >> 8) & 0xFF) as f32 / 255.0;
    let b = (color & 0xFF) as f32 / 255.0;
    unsafe {
        gl::ClearColor(r, g, b, a);
        gl::Clear(gl::COLOR_BUFFER_BIT | gl::DEPTH_BUFFER_BIT);
    }
}

#[loft_native]
#[unsafe(no_mangle)]
pub extern "C" fn loft_gl_destroy_window() {
    GL_READY.with(|c| c.set(false));
    GL.with(|cell| *cell.borrow_mut() = None);
}

#[loft_native]
#[unsafe(no_mangle)]
pub extern "C" fn loft_gl_create_shader(
    vert_ptr: *const u8,
    vert_len: usize,
    frag_ptr: *const u8,
    frag_len: usize,
) -> i64 {
    gl_guard!(0);
    let vert = unsafe { loft_ffi::text(vert_ptr, vert_len) };
    let frag = unsafe { loft_ffi::text(frag_ptr, frag_len) };
    i64::from(shader::compile_program(vert, frag).unwrap_or(0))
}

#[loft_native]
#[unsafe(no_mangle)]
pub extern "C" fn loft_gl_use_shader(program: i64) {
    gl_guard!();
    unsafe {
        gl::UseProgram(program as u32);
    }
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn loft_gl_upload_mesh(
    data_ptr: *const f32,
    n_vertices: u32,
    stride: u32,
    out_vao: *mut u32,
    out_vbo: *mut u32,
) {
    gl_guard!();
    let mut vao = 0u32;
    let mut vbo = 0u32;
    unsafe {
        gl::GenVertexArrays(1, &mut vao);
        gl::GenBuffers(1, &mut vbo);
        gl::BindVertexArray(vao);
        gl::BindBuffer(gl::ARRAY_BUFFER, vbo);
        let byte_size = (n_vertices * stride * 4) as isize;
        gl::BufferData(
            gl::ARRAY_BUFFER,
            byte_size,
            data_ptr.cast(),
            gl::STATIC_DRAW,
        );
        // Position: location 0, 3 floats
        gl::VertexAttribPointer(
            0,
            3,
            gl::FLOAT,
            gl::FALSE,
            (stride * 4) as i32,
            std::ptr::null(),
        );
        gl::EnableVertexAttribArray(0);
        // Normal: location 1, 3 floats at offset 12
        if stride >= 6 {
            gl::VertexAttribPointer(
                1,
                3,
                gl::FLOAT,
                gl::FALSE,
                (stride * 4) as i32,
                (3 * 4) as *const _,
            );
            gl::EnableVertexAttribArray(1);
        }
        // UV: location 2, 2 floats at offset 24 (when stride == 8: pos+normal+uv)
        if stride == 8 {
            gl::VertexAttribPointer(
                2,
                2,
                gl::FLOAT,
                gl::FALSE,
                (stride * 4) as i32,
                (6 * 4) as *const _,
            );
            gl::EnableVertexAttribArray(2);
        }
        // Color: location 2, 4 floats at offset 24 (when stride >= 10: pos+normal+color)
        if stride >= 10 {
            gl::VertexAttribPointer(
                2,
                4,
                gl::FLOAT,
                gl::FALSE,
                (stride * 4) as i32,
                (6 * 4) as *const _,
            );
            gl::EnableVertexAttribArray(2);
        }
        // Growth anchor + birth: location 3 = vec3 anchor at offset 40,
        // location 4 = float birth at offset 52 (when stride >= 14:
        // pos+normal+color+anchor+birth).  Used by the projector's
        // GPU crystal-growth shader to bloom each cell from its centre
        // by age — see tools/audience-demo/projector.loft CRYSTAL_VERT.
        if stride >= 14 {
            gl::VertexAttribPointer(
                3,
                3,
                gl::FLOAT,
                gl::FALSE,
                (stride * 4) as i32,
                (10 * 4) as *const _,
            );
            gl::EnableVertexAttribArray(3);
            gl::VertexAttribPointer(
                4,
                1,
                gl::FLOAT,
                gl::FALSE,
                (stride * 4) as i32,
                (13 * 4) as *const _,
            );
            gl::EnableVertexAttribArray(4);
        }
        gl::BindVertexArray(0);
        *out_vao = vao;
        *out_vbo = vbo;
    }
}

#[loft_native]
#[unsafe(no_mangle)]
pub extern "C" fn loft_gl_draw(vao: i64, n_vertices: i64) {
    gl_guard!();
    unsafe {
        gl::BindVertexArray(vao as u32);
        gl::DrawArrays(gl::TRIANGLES, 0, n_vertices as i32);
        gl::BindVertexArray(0);
    }
}

// ── Store-aware GL functions (interpreter cdylib path — LoftStore/LoftRef) ───
//
// These are called at runtime by the interpreter via dynamic library loading.
// The interpreter's auto-marshalling passes LoftStore + LoftRef for vector args.
// Do NOT call these from native-compiled Rust code (loft_ffi version conflict).

/// Upload a vector<single> as a vertex buffer. Returns VAO handle.
/// stride = floats per vertex (3=pos, 6=pos+normal, 10=pos+normal+color).
/// Interpreter path: receives LoftStore + LoftRef for the data vector.
/// @PLN106 B3 — on Android this store-aware version owns the `loft_gl_upload_vertices`
/// C-ABI symbol (see `n_gl_set_mat4`).
#[loft_native]
#[cfg_attr(not(target_os = "android"), unsafe(no_mangle))]
#[cfg_attr(target_os = "android", unsafe(export_name = "loft_gl_upload_vertices"))]
pub unsafe extern "C" fn n_gl_upload_vertices(
    store: loft_ffi::LoftStore,
    data: loft_ffi::LoftRef,
    stride: i64,
) -> i64 {
    gl_guard!(0);
    let count = unsafe { store.vector_len(&data) };
    let n_vertices = count / stride as u32;
    let data_ptr = unsafe { store.vector_data_ptr(&data) } as *const f32;
    let mut vao = 0u32;
    let mut vbo = 0u32;
    unsafe { loft_gl_upload_mesh(data_ptr, n_vertices, stride as u32, &mut vao, &mut vbo) };
    vao as i64
}

/// Set a mat4 uniform from a vector<float> (16 elements, column-major).
/// Interpreter path: receives LoftStore + LoftRef for the mat vector.
// @PLN106 B3 — on Android the graphics package is linked as a unified rlib and the
// generated C-ABI native calls (`native_cabi=true`) pass `LoftStore` + `LoftRef` and
// link the symbol `loft_gl_set_mat4`. That symbol must therefore be this store-aware
// version, not the raw `loft_gl_set_mat4(*const f64, u32)` (which the registry-based
// interpreter path never links). So on Android export THIS under the C-ABI name and
// cfg the raw one out. (The host currently links the raw symbol — a pre-existing
// mismatch that only surfaces when graphics runs via `--native`, not the interpreter
// or browser.)
#[loft_native]
#[cfg_attr(not(target_os = "android"), unsafe(no_mangle))]
#[cfg_attr(target_os = "android", unsafe(export_name = "loft_gl_set_mat4"))]
pub unsafe extern "C" fn n_gl_set_mat4(
    store: loft_ffi::LoftStore,
    program: i64,
    name_ptr: *const u8,
    name_len: usize,
    mat: loft_ffi::LoftRef,
) {
    gl_guard!();
    let name = unsafe { loft_ffi::text(name_ptr, name_len) };
    // Mat4.m is stored as vector<float> — 16 f64 values in the store.
    // OpenGL needs f32, so we convert on the fly.
    let count = unsafe { store.vector_len(&mat) };
    if count < 16 {
        return;
    }
    let mut buf = [0.0f32; 16];
    for (i, slot) in buf.iter_mut().enumerate() {
        let val = unsafe { store.get_float(mat.rec, 8 + i as u32 * 8, 0) };
        *slot = val as f32;
    }
    let c_name = std::ffi::CString::new(name).unwrap_or_default();
    unsafe {
        let loc = gl::GetUniformLocation(program as u32, c_name.as_ptr());
        if loc >= 0 {
            gl::UniformMatrix4fv(loc, 1, gl::FALSE, buf.as_ptr());
        }
    }
}

// ── Raw-pointer GL functions (native compilation path) ────────────────────
//
// These are called from loft-generated Rust code (--native).  The codegen
// extracts (*const ELEM_TYPE, count: u32) pairs from the stores directly,
// so no LoftStore or LoftRef is involved — no loft_ffi version conflict.

/// Upload a vertex buffer from a raw f32 pointer.  Returns VAO handle.
/// data_ptr/count: elements in the vector<single>; stride: floats per vertex.
/// (Not on Android — `n_gl_upload_vertices` owns the C-ABI symbol there.)
#[cfg(not(target_os = "android"))]
#[unsafe(no_mangle)]
pub unsafe extern "C" fn loft_gl_upload_vertices(
    data_ptr: *const f32,
    count: u32,
    stride: i64,
) -> i64 {
    gl_guard!(0);
    let n_vertices = if stride == 0 {
        0
    } else {
        count / stride as u32
    };
    let mut vao = 0u32;
    let mut vbo = 0u32;
    unsafe { loft_gl_upload_mesh(data_ptr, n_vertices, stride as u32, &mut vao, &mut vbo) };
    vao as i64
}

/// Set a mat4 uniform from a raw f64 pointer (vector<float> element type).
/// Converts the 16 f64 values to f32 before passing to OpenGL.
/// (Not on Android — `n_gl_set_mat4` owns the `loft_gl_set_mat4` C-ABI symbol there.)
#[cfg(not(target_os = "android"))]
#[unsafe(no_mangle)]
pub unsafe extern "C" fn loft_gl_set_mat4(
    program: i64,
    name_ptr: *const u8,
    name_len: usize,
    mat_ptr: *const f64,
    mat_count: u32,
) {
    gl_guard!();
    if mat_count < 16 {
        return;
    }
    let mut buf = [0.0f32; 16];
    for (i, slot) in buf.iter_mut().enumerate() {
        *slot = unsafe { *mat_ptr.add(i) } as f32;
    }
    let name = unsafe { loft_ffi::text(name_ptr, name_len) };
    let c_name = std::ffi::CString::new(name).unwrap_or_default();
    unsafe {
        let loc = gl::GetUniformLocation(program as u32, c_name.as_ptr());
        if loc >= 0 {
            gl::UniformMatrix4fv(loc, 1, gl::FALSE, buf.as_ptr());
        }
    }
}

