// ── Texture from alpha bitmap (for text rendering) ────────────────────

/// Upload an alpha-only bitmap as a GL texture with swizzle to white+alpha.
/// Used for text rendering: the font rasterizer produces alpha bitmaps.
#[unsafe(no_mangle)]
pub extern "C" fn loft_gl_upload_alpha_texture(
    data_ptr: *const u8,
    width: i32,
    height: i32,
) -> i32 {
    gl_guard!(0);
    let mut tex = 0u32;
    unsafe {
        gl::GenTextures(1, &mut tex);
        gl::BindTexture(gl::TEXTURE_2D, tex);
        gl::TexImage2D(
            gl::TEXTURE_2D,
            0,
            gl::RED as i32,
            width,
            height,
            0,
            gl::RED,
            gl::UNSIGNED_BYTE,
            data_ptr.cast(),
        );
        gl::TexParameteri(gl::TEXTURE_2D, gl::TEXTURE_MIN_FILTER, gl::LINEAR as i32);
        gl::TexParameteri(gl::TEXTURE_2D, gl::TEXTURE_MAG_FILTER, gl::LINEAR as i32);
        // Swizzle: sample as (1,1,1,r) so alpha comes from the red channel
        gl::TexParameteri(gl::TEXTURE_2D, gl::TEXTURE_SWIZZLE_A, gl::RED as i32);
        gl::TexParameteri(gl::TEXTURE_2D, gl::TEXTURE_SWIZZLE_R, gl::ONE as i32);
        gl::TexParameteri(gl::TEXTURE_2D, gl::TEXTURE_SWIZZLE_G, gl::ONE as i32);
        gl::TexParameteri(gl::TEXTURE_2D, gl::TEXTURE_SWIZZLE_B, gl::ONE as i32);
        gl::BindTexture(gl::TEXTURE_2D, 0);
    }
    tex as i32
}

/// Rasterize text and upload directly as a GL texture. Returns (tex_id, width, height).
/// Combines loft_gl_rasterize_text + loft_gl_upload_alpha_texture.
#[unsafe(no_mangle)]
pub extern "C" fn loft_gl_text_texture(
    font_idx: i32,
    text_ptr: *const u8,
    text_len: usize,
    size: f32,
    out_width: *mut i32,
    out_height: *mut i32,
) -> i32 {
    gl_guard!(0);
    let s = unsafe { loft_ffi::text(text_ptr, text_len) };
    let (w, h, pixels) = text::rasterize_text(font_idx, s, size);
    unsafe {
        *out_width = w as i32;
        *out_height = h as i32;
    }
    loft_gl_upload_alpha_texture(pixels.as_ptr(), w as i32, h as i32)
}

/// Save pixel data as a PNG file.  Pixels are 0xAARRGGBB packed
/// integers stored in loft's `vector<integer>` (i64 stride post-2c);
/// only the low 32 bits of each element carry the colour.
#[unsafe(no_mangle)]
pub extern "C" fn loft_save_png(
    path_ptr: *const u8,
    path_len: usize,
    width: i64,
    height: i64,
    data_ptr: *const i64,
    data_count: u32,
) -> bool {
    let path = unsafe { loft_ffi::text(path_ptr, path_len) };
    let w = width as u32;
    let h = height as u32;
    if w == 0 || h == 0 || data_count < w * h {
        return false;
    }
    let pixels = unsafe { std::slice::from_raw_parts(data_ptr, (w * h) as usize) };
    // Check if any pixel has alpha < 255 to decide RGB vs RGBA output.
    let has_alpha = pixels
        .iter()
        .any(|&elem| (((elem as u32) >> 24) & 0xFF) != 0xFF);
    let file = match std::fs::File::create(path) {
        Ok(f) => f,
        Err(_) => return false,
    };
    let mut encoder = png::Encoder::new(std::io::BufWriter::new(file), w, h);
    encoder.set_depth(png::BitDepth::Eight);
    if has_alpha {
        encoder.set_color(png::ColorType::Rgba);
        let mut rgba = Vec::with_capacity((w * h * 4) as usize);
        for &elem in pixels {
            let px = elem as u32;
            rgba.push(((px >> 16) & 0xFF) as u8); // R
            rgba.push(((px >> 8) & 0xFF) as u8); // G
            rgba.push((px & 0xFF) as u8); // B
            rgba.push(((px >> 24) & 0xFF) as u8); // A
        }
        let mut writer = match encoder.write_header() {
            Ok(w) => w,
            Err(_) => return false,
        };
        writer.write_image_data(&rgba).is_ok()
    } else {
        encoder.set_color(png::ColorType::Rgb);
        let mut rgb = Vec::with_capacity((w * h * 3) as usize);
        for &elem in pixels {
            let px = elem as u32;
            rgb.push(((px >> 16) & 0xFF) as u8); // R
            rgb.push(((px >> 8) & 0xFF) as u8); // G
            rgb.push((px & 0xFF) as u8); // B
        }
        let mut writer = match encoder.write_header() {
            Ok(w) => w,
            Err(_) => return false,
        };
        writer.write_image_data(&rgb).is_ok()
    }
}

/// Capture the current GL back-buffer to an RGB PNG.  Reads `GL_BACK`
/// (call before `gl_swap_buffers`, after the frame's draws) and flips the
/// rows, since GL's origin is bottom-left while PNG is top-left.  Lets us
/// inspect the live 3D output even on a headless / Wayland desktop where
/// the window itself can't be grabbed by external tools.
#[loft_native]
#[unsafe(no_mangle)]
pub extern "C" fn loft_gl_screenshot(
    width: i64,
    height: i64,
    path_ptr: *const u8,
    path_len: usize,
) -> bool {
    gl_guard!(false);
    if width <= 0 || height <= 0 {
        return false;
    }
    let path = unsafe { loft_ffi::text(path_ptr, path_len) };
    let w = width as usize;
    let h = height as usize;
    let mut buf = vec![0u8; w * h * 4];
    unsafe {
        gl::PixelStorei(gl::PACK_ALIGNMENT, 1);
        gl::ReadBuffer(gl::BACK);
        gl::ReadPixels(
            0,
            0,
            width as i32,
            height as i32,
            gl::RGBA,
            gl::UNSIGNED_BYTE,
            buf.as_mut_ptr() as *mut std::ffi::c_void,
        );
    }
    let file = match std::fs::File::create(path) {
        Ok(f) => f,
        Err(_) => return false,
    };
    let mut encoder = png::Encoder::new(std::io::BufWriter::new(file), w as u32, h as u32);
    encoder.set_depth(png::BitDepth::Eight);
    encoder.set_color(png::ColorType::Rgb);
    let mut writer = match encoder.write_header() {
        Ok(wr) => wr,
        Err(_) => return false,
    };
    let mut rgb = Vec::with_capacity(w * h * 3);
    for row in (0..h).rev() {
        let base = row * w * 4;
        for col in 0..w {
            let i = base + col * 4;
            rgb.push(buf[i]);
            rgb.push(buf[i + 1]);
            rgb.push(buf[i + 2]);
        }
    }
    writer.write_image_data(&rgb).is_ok()
}

/// Load an image file (PNG, JPG) and upload it as a GL texture. Returns texture ID (0 on failure).
#[loft_native]
#[unsafe(no_mangle)]
pub extern "C" fn loft_gl_load_texture(path_ptr: *const u8, path_len: usize) -> i64 {
    gl_guard!(0);
    let path = unsafe { loft_ffi::text(path_ptr, path_len) };
    let img = match image::open(path) {
        Ok(img) => img.to_rgba8(),
        Err(_) => return 0,
    };
    let (w, h) = img.dimensions();
    unsafe { loft_gl_upload_texture(img.as_raw().as_ptr(), w, h) as i64 }
}

/// Upload Canvas pixel data (0xAARRGGBB packed integers) as a GL RGBA
/// texture.  Post-2c, loft's `vector<integer>` is i64-stride storage —
/// each element occupies 8 bytes, with the packed colour in the LOW 32
/// bits and the high 32 bits zero.  Reading at the old i32 stride
/// (4-byte pixels) sees only every other "pixel" populated; the rest
/// were the high-half of the prior i64 = 0 = transparent black, which
/// shows up as moiré on textured surfaces and as missing pixels on
/// rasterised text (Brick Buster's title / HUD).  Read at i64 stride
/// to match the loft allocation; only the low 32 bits carry the
/// colour.
///
/// C58: canonical `(0, 0) = canvas top-left` — no upload-side Y flip.
/// GL's glTexImage2D stores the first buffer row as the texture's
/// bottom row, so canvas-top lives at TC.y=0 after upload.  The 2D
/// orthographic projection's `-2/H` already compensates for that when
/// mapping user-supplied top-left screen coords to GL clip-space, so
/// sprite and texture shaders can sample with identity V (no per-shader
/// flip).
/// @PLN106 B3 — on Android the store-aware `n_gl_upload_canvas` owns the
/// `loft_gl_upload_canvas` C-ABI symbol and calls this by Rust name, so drop the
/// `#[no_mangle]` here (keep the fn — it does the actual texture upload).
#[cfg_attr(not(target_os = "android"), unsafe(no_mangle))]
pub extern "C" fn loft_gl_upload_canvas(
    data_ptr: *const i64,
    data_count: u32,
    width: i64,
    height: i64,
) -> i64 {
    gl_guard!(0);
    let w = width as u32;
    let h = height as u32;
    if w == 0 || h == 0 || data_count < w * h {
        return 0;
    }
    let pixels = unsafe { std::slice::from_raw_parts(data_ptr, (w * h) as usize) };
    let mut rgba = Vec::with_capacity((w * h * 4) as usize);
    for &elem in pixels {
        let px = elem as u32; // low 32 bits hold the packed colour
        rgba.push(((px >> 16) & 0xFF) as u8); // R
        rgba.push(((px >> 8) & 0xFF) as u8); // G
        rgba.push((px & 0xFF) as u8); // B
        rgba.push(((px >> 24) & 0xFF) as u8); // A
    }
    unsafe { loft_gl_upload_texture(rgba.as_ptr(), w, h) as i64 }
}

// Interpreter wrapper — extracts vector data via LoftStore + LoftRef.
// Cannot use vec_wrapper! because the auto-marshaller's store snapshot
// may be stale for canvas data (issue #120 store lifecycle).
// @PLN106 B3 — on Android this owns the `loft_gl_upload_canvas` C-ABI symbol (see
// `n_gl_set_mat4`); it reads the canvas vector from the store, so the C-ABI call's
// `data_count` no longer arrives as 0.
#[loft_native]
#[cfg_attr(not(target_os = "android"), unsafe(no_mangle))]
#[cfg_attr(target_os = "android", unsafe(export_name = "loft_gl_upload_canvas"))]
pub unsafe extern "C" fn n_gl_upload_canvas(
    store: loft_ffi::LoftStore,
    data: loft_ffi::LoftRef,
    width: i64,
    height: i64,
) -> i64 {
    gl_guard!(0);
    let count = unsafe { store.vector_len(&data) };
    let data_ptr = unsafe { store.vector_data_ptr(&data) } as *const i64;
    loft_gl_upload_canvas(data_ptr, count, width, height)
}
loft_ffi::vec_wrapper!(n_save_png, loft_save_png(path_ptr: *const u8, path_len: usize, width: i64, height: i64, data: vec<i64>) -> bool);
loft_ffi::vec_wrapper!(n_rasterize_text_into, loft_rasterize_text_into(font_idx: i64, text_ptr: *const u8, text_len: usize, size: f64, buf: vec<i64>) -> i64);

// @PLN106 B3 — export the store-aware `vec_wrapper!` output under the `loft_*` C-ABI
// symbol on Android (the macro can't set `export_name` itself), so the generated
// `native_cabi` decls (LoftStore + LoftRef) resolve to the store-aware version
// rather than the raw ptr+count one. Same fix as `n_gl_set_mat4` for the two
// `vec_wrapper!` functions a graphics program can reach.
#[cfg(target_os = "android")]
#[unsafe(export_name = "loft_rasterize_text_into")]
pub unsafe extern "C" fn __loft_android_rasterize_text_into(
    store: loft_ffi::LoftStore,
    font: i64,
    content_ptr: *const u8,
    content_len: usize,
    size: f64,
    buf: loft_ffi::LoftRef,
) -> i64 {
    unsafe { n_rasterize_text_into(store, font, content_ptr, content_len, size, buf) }
}

/// Return the line height in pixels for a font at the given size — fontdue's
/// real `new_line_size` (@P340/#252), falling back to `size * 1.2` for a font
/// with no horizontal metrics.
#[loft_native]
#[unsafe(no_mangle)]
pub extern "C" fn loft_text_height(font_idx: i64, size: f64) -> i64 {
    text::font_line_height(font_idx as i32, size as f32).ceil() as i64
}

/// @P340 — return the font's ASCENT in pixels (baseline → top of glyphs) from
/// fontdue's real horizontal line metrics.  Lets callers baseline-align
/// mixed-size text: the top-anchored `gl_draw_text(x, y)` places the baseline
/// at `y + gl_font_ascent(font, size)`, so two sizes sharing a baseline are
/// drawn at `y_i = baseline - gl_font_ascent(font, size_i)`.
#[loft_native]
#[unsafe(no_mangle)]
pub extern "C" fn loft_gl_font_ascent(font_idx: i64, size: f64) -> f64 {
    f64::from(text::font_ascent(font_idx as i32, size as f32))
}

/// Rasterize text and write alpha values (0-255) into a pre-allocated
/// `vector<integer>` buffer.  Post-2c, `integer` storage is i64 stride
/// — write at i64 stride to match.  Pre-2c i32-stride writes left every
/// other slot's high half zero, which loft then read as a packed
/// alpha pair → only the low byte (alpha[2k]) survived the `& 255`
/// mask in `rgba`, so loft canvas pixel `k` showed `alpha[2k]` and
/// pixel `k+1` from row index `k+1` showed `alpha[2k+2]` — text
/// rasterised with every-other-pixel zero, the checker overlay
/// visible on Brick Buster's title.
/// @PLN106 B3 — on Android the store-aware `n_rasterize_text_into` (vec_wrapper!)
/// owns the `loft_rasterize_text_into` C-ABI symbol (via the export wrapper below)
/// and calls this by Rust name, so drop the `#[no_mangle]` here.
#[cfg_attr(not(target_os = "android"), unsafe(no_mangle))]
pub extern "C" fn loft_rasterize_text_into(
    font_idx: i64,
    text_ptr: *const u8,
    text_len: usize,
    size: f64,
    buf_ptr: *const i64,
    buf_count: u32,
) -> i64 {
    let s = unsafe { loft_ffi::text(text_ptr, text_len) };
    let (bw, bh, bitmap) = text::rasterize_text(font_idx as i32, s, size as f32);
    let count = (bw * bh) as usize;
    if count == 0 || buf_ptr.is_null() {
        return 0;
    }
    let buf = unsafe { std::slice::from_raw_parts_mut(buf_ptr as *mut i64, buf_count as usize) };
    for (i, &a) in bitmap.iter().enumerate() {
        if i >= buf.len() {
            break;
        }
        buf[i] = i64::from(a);
    }
    bw as i64
}

/// Set line width for GL_LINES rendering.
#[loft_native]
#[unsafe(no_mangle)]
pub extern "C" fn loft_gl_line_width(width: f64) {
    gl_guard!();
    unsafe {
        gl::LineWidth(width as f32);
    }
}

/// Set point size for GL_POINTS rendering.
#[loft_native]
#[unsafe(no_mangle)]
pub extern "C" fn loft_gl_point_size(size: f64) {
    gl_guard!();
    unsafe {
        gl::PointSize(size as f32);
    }
}

