// ── Text / Font C-ABI exports (GL3) ─────────────────────────────────────

/// Load a font from a file path. Returns font index (>= 0) on success, or
/// `i32::MIN` on error — that's loft's null sentinel for `integer`, so the
/// loft-side `if !font { … }` check works correctly. (Returning -1 would
/// look like a valid handle to loft, since -1 is not the null sentinel.
/// The bug that caused Brick Buster's score counter and every text texture in
/// 00-smoke.loft to be silently invisible was: -1 returned here, the loft
/// fallback path skipped, font_idx=-1 cast to usize=MAX in measure_text,
/// `fonts.get()` returns None, width returned as 0, canvas allocated as
/// 5×25, no glyphs fit.)
#[loft_native]
#[unsafe(no_mangle)]
pub extern "C" fn loft_gl_load_font(path_ptr: *const u8, path_len: usize) -> i64 {
    let path = unsafe { loft_ffi::text(path_ptr, path_len) };
    match std::fs::read(path) {
        // load_font_bytes returns a small font index, or -1 on parse failure.
        // Map -1 to loft's null sentinel (i64::MIN under the i64 ABI) so the
        // loft-side `if !font { … }` check fires — see the doc-comment above
        // for why a bare -1 would slip through as a valid-looking handle.
        Ok(data) => {
            let idx = text::load_font_bytes(&data);
            if idx < 0 { i64::MIN } else { i64::from(idx) }
        }
        Err(_) => i64::MIN,
    }
}

/// Measure text width in pixels at the given font size.
/// Takes and returns f64 to match loft's `float` type.
#[loft_native]
#[unsafe(no_mangle)]
pub extern "C" fn loft_gl_measure_text(
    font_idx: i64,
    text_ptr: *const u8,
    text_len: usize,
    size: f64,
) -> f64 {
    let s = unsafe { loft_ffi::text(text_ptr, text_len) };
    text::measure_text(font_idx as i32, s, size as f32) as f64
}

/// Rasterize text into an alpha bitmap.
/// Caller must free the returned buffer with `loft_gl_free_bitmap`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn loft_gl_rasterize_text(
    font_idx: i32,
    text_ptr: *const u8,
    text_len: usize,
    size: f32,
    out_width: *mut u32,
    out_height: *mut u32,
    out_pixels: *mut *mut u8,
    out_pixels_len: *mut usize,
) {
    let s = unsafe { loft_ffi::text(text_ptr, text_len) };
    let (w, h, mut pixels) = text::rasterize_text(font_idx, s, size);
    unsafe {
        *out_width = w;
        *out_height = h;
        *out_pixels_len = pixels.len();
        *out_pixels = pixels.as_mut_ptr();
    }
    std::mem::forget(pixels);
}

/// Free a bitmap buffer allocated by `loft_gl_rasterize_text`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn loft_gl_free_bitmap(ptr: *mut u8, len: usize) {
    if !ptr.is_null() && len > 0 {
        drop(unsafe { Vec::from_raw_parts(ptr, len, len) });
    }
}

// ── Texture C-ABI exports (GL5.5) ──────────────────────────────────────

/// Upload an RGBA texture from a pixel buffer. Returns the texture ID.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn loft_gl_upload_texture(
    data_ptr: *const u8,
    width: u32,
    height: u32,
) -> u32 {
    gl_guard!(0);
    let mut tex = 0u32;
    unsafe {
        gl::GenTextures(1, &mut tex);
        gl::BindTexture(gl::TEXTURE_2D, tex);
        gl::TexParameteri(gl::TEXTURE_2D, gl::TEXTURE_MIN_FILTER, gl::LINEAR as i32);
        gl::TexParameteri(gl::TEXTURE_2D, gl::TEXTURE_MAG_FILTER, gl::LINEAR as i32);
        gl::TexParameteri(gl::TEXTURE_2D, gl::TEXTURE_WRAP_S, gl::CLAMP_TO_EDGE as i32);
        gl::TexParameteri(gl::TEXTURE_2D, gl::TEXTURE_WRAP_T, gl::CLAMP_TO_EDGE as i32);
        gl::TexImage2D(
            gl::TEXTURE_2D,
            0,
            gl::RGBA as i32,
            width as i32,
            height as i32,
            0,
            gl::RGBA,
            gl::UNSIGNED_BYTE,
            data_ptr.cast(),
        );
        gl::BindTexture(gl::TEXTURE_2D, 0);
    }
    tex
}

/// Bind a texture to a texture unit for rendering.
#[loft_native]
#[unsafe(no_mangle)]
pub extern "C" fn loft_gl_bind_texture(texture_id: i64, unit: i64) {
    gl_guard!();
    unsafe {
        gl::ActiveTexture(gl::TEXTURE0 + unit as u32);
        gl::BindTexture(gl::TEXTURE_2D, texture_id as u32);
    }
}

/// Delete a texture.
#[loft_native]
#[unsafe(no_mangle)]
pub extern "C" fn loft_gl_delete_texture(texture_id: i64) {
    gl_guard!();
    let texture_id = texture_id as u32;
    unsafe {
        gl::DeleteTextures(1, &texture_id);
    }
}
